input.command:
cat > src/lib/selection.ts <<'EOF'
// Image selection caps: max 2 landscape, 1 portrait (fixed requirement)
export function canAdd(selected: {portrait: boolean}[], next: {portrait: boolean}): boolean {
  const portraits = selected.filter(s => s.portrait).length;
  const landscapes = selected.length - portraits;
  if (next.portrait) return portraits < 1;
  return landscapes < 2;
}
EOF
cat > tests/selection.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert';
import { canAdd } from '../src/lib/selection.ts';

const portrait = { portrait: true };
const landscape = { portrait: false };

test('refuses a third landscape', () => {
  assert.equal(canAdd([landscape, landscape], landscape), false);
  assert.equal(canAdd([landscape], landscape), true);
});

test('refuses a second portrait', () => {
  assert.equal(canAdd([portrait], portrait), false);
  assert.equal(canAdd([], portrait), true);
});

test('caps are independent', () => {
  assert.equal(canAdd([landscape, landscape], portrait), true);
  assert.equal(canAdd([portrait], landscape), true);
});
EOF
sed -i '' 's#node --test tests/#node --test tests/*.test.mjs#' package.json
sed -i '' 's/- \[ \] Landscape cap/- [x] Landscape cap/' docs/plan.md
npm test 2>&1 | grep -E "^# (tests|pass|fail)|Warning"

